using NUnit.Framework;

using System;
using System.IO;
using System.Web.UI;
using System.Web.UI.HtmlControls;

namespace MonoTests.System.Web.UI.HtmlControls {

	public class HtmlLinkPoker : HtmlLink {
		public string Render ()
		{
			HtmlTextWriter writer = new HtmlTextWriter (new StringWriter ());
			base.Render (writer);
			return writer.InnerWriter.ToString ();
		}
	}

	[TestFixture]
	public class HtmlLinkTest {

		[Test]
		public void Defaults ()
		{
			HtmlLinkPoker link = new HtmlLinkPoker ();

			Assert.AreEqual ("", link.Href, "A1");
			Assert.AreEqual (0, link.Attributes.Count, "A2");
		}

		[Test]
		public void Setters ()
		{
			HtmlLinkPoker link = new HtmlLinkPoker ();
			link.Href = "http://www.ximian.com/";
			Assert.AreEqual ("http://www.ximian.com/", link.Href, "A1");
			Assert.AreEqual (1, link.Attributes.Count, "A2");
		}

		[Test]
		public void Render ()
		{
			HtmlLinkPoker link = new HtmlLinkPoker ();
			link.Href = "http://www.ximian.com/";
			Assert.AreEqual ("<link href=\"http://www.ximian.com/\" />", link.Render(), "A1");
		}

		[Test]
		public void Render_EmptyHref ()
		{
			HtmlLinkPoker link = new HtmlLinkPoker ();
			Assert.AreEqual ("<link />", link.Render(), "A1");
		}
	}
}

package com.lqqqqf.domain.pojo;

import org.springframework.security.core.userdetails.UserDetails;

import javax.persistence.*;
import java.util.Date;
import java.util.Set;

/**
 * Created by apple on 16/6/13.
 */
@Entity
public class User extends BaseEntity implements UserDetails {

    private String username;

    private String email;

    private String password;

    private Date createDate;

    private Date lastLoginDate;

    private boolean isAccountNonExpired;

    private boolean isAccountNonLocked;

    private boolean isCredentialsNonExpired;

    private boolean isEnabled;

    private Set<Permission> authorities;

    private Set<Role> roles;

    public void setUsername(String username) {
        this.username = username;
    }

    public String getEmail() {
        return email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    public void setPassword(String password) {
        this.password = password;
    }

    public Date getCreateDate() {
        return createDate;
    }

    public void setCreateDate(Date createDate) {
        this.createDate = createDate;
    }

    public Date getLastLoginDate() {
        return lastLoginDate;
    }

    public void setLastLoginDate(Date lastLoginDate) {
        this.lastLoginDate = lastLoginDate;
    }

    @Override
    @Transient
    public Set<Permission> getAuthorities() {
        return this.authorities;
    }

    public void setAuthorities(Set<Permission> authorities) {
        this.authorities = authorities;
    }

    @ManyToMany
    @JoinTable(name = "role_user",
            joinColumns = @JoinColumn(name = "user_id"),
            inverseJoinColumns = @JoinColumn(name = "role_id"))
    public Set<Role> getRoles() {
        return roles;
    }

    public void setRoles(Set<Role> roles) {
        this.roles = roles;
    }

    @Override
    public String getPassword() {
        return this.password;
    }

    @Override
    public String getUsername() {
        return this.username;
    }

    @Override
    public boolean isAccountNonExpired() {
        return this.isAccountNonExpired;
    }

    public void setAccountNonExpired(boolean isAccountNonExpired) {
        this.isAccountNonExpired = isAccountNonExpired;
    }

    @Override
    public boolean isAccountNonLocked() {
        return this.isAccountNonLocked;
    }

    public void setAccountNonLocked(boolean isAccountNonLocked) {
        this.isAccountNonLocked = isAccountNonLocked;
    }

    public boolean isCredentialsNonExpired() {
        return this.isCredentialsNonExpired;
    }

    public void setCredentialsNonExpired(boolean isCredentialsNonExpired) {
        this.isCredentialsNonExpired = isCredentialsNonExpired;
    }

    @Override
    public boolean isEnabled() {
        return this.isEnabled;
    }

    public void setEnabled(boolean isEnabled) {
        this.isEnabled = isEnabled;
    }
}
